import sys
import logging
from ta_uexgate.uex_json_rpc_client import UExJsonRpcClient

if sys.version_info.major == 2:
    logging.warning("Python {}.{} is used. Be aware that some features may not work. "
                    "Please use Python 3.6 or higher if possible.".format(sys.version_info.major,
                                                                          sys.version_info.minor))
    possible_interface_as_class = [UExJsonRpcClient]
    possible_interface_as_str = ['UExJsonRpcClient']
else:
    class CodecWrnFilter(logging.Filter):
        @staticmethod
        def filter(record):
            if record.getMessage() == "Native term ETF codec library import failed, falling back to slower Python impl":
                return False
            return True

    logging.getLogger("term").addFilter(CodecWrnFilter())

    from ta_uexgate.uex_interface import UExInterface
    possible_interface_as_class = [UExInterface, UExJsonRpcClient]
    possible_interface_as_str = ['UExInterface', 'UExJsonRpcClient']


class UExInterfaceFactory(object):
    def __init__(self):
        pass

    @staticmethod
    def get_uex_interface(host, connection_type=None):
        if connection_type is None:
            return {'127.0.0.1': possible_interface_as_class[-1]}.get(host, UExJsonRpcClient)(host)
        elif connection_type in possible_interface_as_class:
            return connection_type(host)
        elif connection_type in possible_interface_as_str:
            return eval(connection_type)(host)
        else:
            raise ValueError('Wrong connection_type value: {}. Use one of a: {}'.format(connection_type,
                                                                                        possible_interface_as_str))
